using System;
using Avalonia.Controls;
using Avalonia.Media.Imaging;
using Avalonia.Platform;
using Avalonia.Styling;

namespace SlimCodeDesktop.Themes;

/// <summary>
/// The app icon as Avalonia resources. Sources are the SVGs in assets/icon/;
/// the raster files are generated by tools/make-icons.cs.
/// </summary>
public static class AppIcons
{
   private const string BaseUri = "avares://SlimCodeDesktop/assets/icon/";

   private static WindowIcon? s_window;
   private static Bitmap?     s_large;
   private static Bitmap?     s_small;

   /// <summary>
   /// Window / taskbar icon. Windows gets the multi-size .ico (its 16/24 px
   /// frames are the simplified glyph); elsewhere the 256 px PNG, which is
   /// what X11 window managers expect.
   /// </summary>
   public static WindowIcon Window =>
      s_window ??= new WindowIcon(_Open(OperatingSystem.IsWindows() ? "slimcode.ico" : "slimcode-256.png"));

   /// <summary>256 px robot, for the About page.</summary>
   public static Bitmap Large => s_large ??= new Bitmap(_Open("slimcode-256.png"));

   /// <summary>32 px simplified glyph, drawn at 16 px in the title bar.</summary>
   public static Bitmap Small => s_small ??= new Bitmap(_Open("slimcode-small-32.png"));

   /// <summary>
   /// Gives every window -- main window and all dialogs -- the app icon
   /// without each one having to set it.
   /// </summary>
   public static void ApplyToAllWindows(Avalonia.Application app)
   {
      app.Styles.Add(new Style(x => x.Is<Avalonia.Controls.Window>())
      {
         Setters = { new Setter(Avalonia.Controls.Window.IconProperty, Window) },
      });
   }

   private static System.IO.Stream _Open(string file) =>
      AssetLoader.Open(new Uri(BaseUri + file));
}
